const {lang,t,catalog}=JSON.parse(document.querySelector('#site-data').textContent);
try{localStorage.setItem('lc_lang',lang)}catch{}
const dialog=document.querySelector('#detail'), image=document.querySelector('#detail-image'),zoom=document.querySelector('.zoom'),tabs=[...document.querySelectorAll('[data-view]')];
let current=0,view=0,trigger=null,start=null,suppressClick=false;
function updateView(next){view=(next+3)%3;const p=catalog[current];image.src=view===2?`/assets/originals/${p.id}.jpg`:`/assets/campaign/${p.id}${view===1?'-detail':''}.webp`;image.alt=`${p[lang].name} — ${[t.campaign,t.detail,t.original][view]}`;tabs.forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.view)===view)));zoom.classList.remove('is-zoomed');zoom.setAttribute('aria-label',t.zoom);zoom.setAttribute('aria-pressed','false');}
function open(index,opener){current=index;trigger=opener;const p=catalog[index],c=p[lang];document.querySelector('#detail-name').textContent=c.name;document.querySelector('#detail-price').textContent=`US$${p.price}`;document.querySelector('#detail-state').textContent=index===0?t.available:t.preorder;document.querySelector('#detail-description').textContent=c.description;document.querySelector('#detail-focus').textContent=c.detail;document.querySelector('#order-note').textContent=index===0?t.availNote:t.preNote;updateView(0);dialog.showModal();document.querySelector('.close').focus({preventScroll:true});document.body.classList.add('modal-open');}
document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>open(Number(b.dataset.open),b)));
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');trigger?.focus({preventScroll:true});});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
tabs.forEach(b=>b.addEventListener('click',()=>updateView(Number(b.dataset.view))));document.querySelector('.previous').addEventListener('click',()=>updateView(view-1));document.querySelector('.next').addEventListener('click',()=>updateView(view+1));
zoom.addEventListener('click',()=>{if(suppressClick){suppressClick=false;return;}const enlarged=zoom.classList.toggle('is-zoomed');zoom.setAttribute('aria-pressed',String(enlarged));zoom.setAttribute('aria-label',enlarged?t.unzoom:t.zoom);});
zoom.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')start={x:e.clientX,y:e.clientY};});zoom.addEventListener('pointerup',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)){suppressClick=true;updateView(view+(dx<0?1:-1));}});zoom.addEventListener('pointercancel',()=>start=null);
document.addEventListener('keydown',e=>{if(dialog.open&&e.key==='ArrowRight'){e.preventDefault();updateView(view+1);}if(dialog.open&&e.key==='ArrowLeft'){e.preventDefault();updateView(view-1);}});
document.querySelectorAll('.languages a').forEach(a=>a.addEventListener('click',()=>{try{localStorage.setItem('lc_lang',a.lang)}catch{}}));

dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const focusable=[...dialog.querySelectorAll('button,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){e.preventDefault();first.focus();}});
